MOD = 1_000_000_007

class Field:
    P = MOD

    def __init__(self, a):
        self.v = self.cv(a)

    @staticmethod
    def hi(a):
        if a >= Field.P:
            a -= Field.P
        return a

    @staticmethod
    def lo(a):
        if a < 0:
            a += Field.P
        return a

    @staticmethod
    def cv(a):
        return Field.lo(int(a) % Field.P)

    @classmethod
    def new(cls, a):
        return cls(a)

    @classmethod
    def new_unchecked(cls, a):
        obj = cls(0)
        obj.v = a
        return obj

    def inv(self):
        return self.pow(Field.P - 2)

    def pow(self, b):
        b = int(b)
        if b == 0:
            return Field(1)
        res = self.pow(b // 2)
        res *= res
        if b % 2 == 1:
            res *= self
        return res

    def __add__(self, other):
        return Field.new_unchecked(Field.hi(self.v + other.v))

    def __sub__(self, other):
        return Field.new_unchecked(Field.lo(self.v - other.v))

    def __mul__(self, other):
        return Field.new_unchecked(Field.cv(self.v * other.v))

    def __truediv__(self, other):
        return self * other.inv()

    def __neg__(self):
        return Field.new_unchecked(Field.lo(-self.v))

    def __iadd__(self, other):
        self.v = Field.hi(self.v + other.v)
        return self

    def __isub__(self, other):
        self.v = Field.lo(self.v - other.v)
        return self

    def __imul__(self, other):
        self.v = Field.cv(self.v * other.v)
        return self

    def __itruediv__(self, other):
        self.__imul__(other.inv())
        return self

    def __str__(self):
        return str(self.v)

Z0 = Field(0)
Z1 = Field(1)

