        self.n = n
        f = [None] * (n + 1)
        f[0] = Z1
        for i in range(1, n + 1):
            f[i] = f[i - 1] * Field.new(i)
        fi = [Z1] * (n + 1)
        fi[n] = f[n].inv()
        for i in range(n - 1, -1, -1):
            fi[i] = fi[i + 1] * Field.new(i + 1)
